import json, re

def get_pre_files(pre):
    files = {}
    if isinstance(pre, dict):
        for k, v in pre.items():
            if isinstance(k, str) and k.startswith("/testbed/data"):
                files[k] = "" if v is None else str(v)
    return files

def apply_write(files, w):
    if not isinstance(w, dict):
        return
    path = w.get("path")
    if not (isinstance(path, str) and path.startswith("/testbed/data")):
        return
    if w.get("success") is False:
        return
    op = w.get("op") or w.get("operation") or w.get("type") or w.get("kind") or ""
    content = w.get("content")
    if content is None:
        content = w.get("text")
    if content is None:
        content = w.get("value")
    if op in ("write", "create", "overwrite", "put"):
        files[path] = "" if content is None else str(content)
    elif op in ("append",):
        files[path] = files.get(path, "") + ("" if content is None else str(content))
    elif op in ("delete", "remove", "unlink"):
        files.pop(path, None)
    else:
        if content is not None:
            files[path] = str(content)

